namespace Challenges
{
    /// <summary>
    /// Classes the current layouts author on every server-addressed panel: the client state before any write.
    /// Data in <c>HudAuthored.g.cs</c>, generated by <c>make panorama</c> from <c>tracker_vN.xml</c> / <c>menu_vN.xml</c>.
    /// </summary>
    internal static partial class HudAuthored
    {
        public static bool HasClass(string panelId, string className) =>
            ClassesById.TryGetValue(panelId, out string[]? classes)
            && Array.IndexOf(classes, className) >= 0;

        /// <summary>Authored <c>p0</c>…<c>p100</c> ladder value of the panel, or -1 when it has none.</summary>
        public static int Percent(string panelId)
        {
            if (!ClassesById.TryGetValue(panelId, out string[]? classes))
            {
                return -1;
            }

            foreach (string cls in classes)
            {
                if (cls.Length > 1 && cls[0] == 'p' && int.TryParse(cls.AsSpan(1), out int percent)
                    && percent is >= 0 and <= 100)
                {
                    return percent;
                }
            }

            return -1;
        }
    }
}
